// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract AsmProbe {
    uint256 public value;

    function set(uint256 newValue) public {
        assembly {
            function clamp(v) -> w {
                w := v
                if gt(v, 100) {
                    w := 100
                }
            }
            if gt(newValue, 1000) {
                revert(0, 0)
            }
            sstore(1, clamp(newValue))
        }
        value = newValue;
    }
}
